begin;
alter table public.employee_occurrences add constraint employee_occurrences_scope_unique unique (tenant_id,company_id,id);
alter table public.payroll_events add constraint payroll_events_scope_unique unique (tenant_id,company_id,id);
create table public.employee_occurrence_payroll_links(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,occurrence_id uuid not null,competence_month date not null,payroll_event_id uuid not null,event_kind text not null check(event_kind in('absence','dsr')),generated_amount numeric(14,2) not null check(generated_amount>0),generated_by uuid references auth.users(id) on delete set null,generated_at timestamptz not null default now(),constraint employee_occurrence_payroll_links_month_ck check(competence_month=date_trunc('month',competence_month)::date),constraint employee_occurrence_payroll_links_occurrence_fk foreign key(tenant_id,company_id,occurrence_id) references public.employee_occurrences(tenant_id,company_id,id) on delete restrict,constraint employee_occurrence_payroll_links_event_fk foreign key(tenant_id,company_id,payroll_event_id) references public.payroll_events(tenant_id,company_id,id) on delete restrict,constraint employee_occurrence_payroll_links_unique unique(tenant_id,company_id,occurrence_id,competence_month,event_kind));
create index employee_occurrence_payroll_links_occurrence_idx on public.employee_occurrence_payroll_links(tenant_id,company_id,occurrence_id);
create index employee_occurrence_payroll_links_event_idx on public.employee_occurrence_payroll_links(tenant_id,company_id,payroll_event_id);
create index employee_occurrence_payroll_links_generated_by_idx on public.employee_occurrence_payroll_links(generated_by);
alter table public.employee_occurrence_payroll_links enable row level security;
create policy employee_occurrence_payroll_links_select on public.employee_occurrence_payroll_links for select to authenticated using(app_private.can_access_company(tenant_id,company_id));
create policy employee_occurrence_payroll_links_insert on public.employee_occurrence_payroll_links for insert to authenticated with check(app_private.can_manage_company(tenant_id,company_id));
create policy employee_occurrence_payroll_links_update on public.employee_occurrence_payroll_links for update to authenticated using(app_private.can_manage_company(tenant_id,company_id)) with check(app_private.can_manage_company(tenant_id,company_id));
create policy employee_occurrence_payroll_links_delete on public.employee_occurrence_payroll_links for delete to authenticated using(app_private.can_manage_company(tenant_id,company_id));
create or replace function public.sync_employee_occurrence_payroll(p_occurrence_id uuid,p_competence_month date,p_event_kind text,p_amount numeric,p_cost_center_id uuid default null) returns uuid language plpgsql security invoker set search_path='' as $$ declare v_occ public.employee_occurrences%rowtype;v_existing public.employee_occurrence_payroll_links%rowtype;v_event_id uuid;v_month_end date;v_overlap_start date;v_overlap_end date;v_quantity integer; begin if auth.uid() is null then raise exception 'authentication required';end if;if p_competence_month is null or p_competence_month<>date_trunc('month',p_competence_month)::date then raise exception 'competence month must be first day of month';end if;if p_event_kind not in('absence','dsr') then raise exception 'invalid payroll event kind';end if;if p_amount is null or p_amount<=0 or round(p_amount,2)<>p_amount then raise exception 'amount must be positive with at most two decimals';end if;select * into v_occ from public.employee_occurrences where id=p_occurrence_id;if not found then raise exception 'occurrence not found or not accessible';end if;if not app_private.can_manage_company(v_occ.tenant_id,v_occ.company_id) then raise exception 'company management permission required';end if;if v_occ.status<>'active' then raise exception 'occurrence is not active';end if;if v_occ.payroll_effect<>p_event_kind then raise exception 'occurrence payroll effect does not match event kind';end if;v_month_end:=(p_competence_month+interval '1 month - 1 day')::date;v_overlap_start:=greatest(v_occ.starts_on,p_competence_month);v_overlap_end:=least(v_occ.ends_on,v_month_end);if v_overlap_end<v_overlap_start then raise exception 'occurrence does not overlap competence';end if;v_quantity:=(v_overlap_end-v_overlap_start)+1;select * into v_existing from public.employee_occurrence_payroll_links where tenant_id=v_occ.tenant_id and company_id=v_occ.company_id and occurrence_id=v_occ.id and competence_month=p_competence_month and event_kind=p_event_kind;if found then if v_existing.generated_amount<>p_amount::numeric(14,2) then raise exception 'occurrence already synced with different amount';end if;return v_existing.payroll_event_id;end if;if exists(select 1 from public.payroll_closings pc where pc.tenant_id=v_occ.tenant_id and pc.company_id=v_occ.company_id and pc.employment_contract_id=v_occ.employment_contract_id and pc.competence_month=p_competence_month and pc.status='closed') then raise exception 'payroll competence already closed';end if;select event_id into v_event_id from public.record_payroll_event(v_occ.tenant_id,v_occ.company_id,v_occ.employment_contract_id,p_cost_center_id,p_competence_month,v_overlap_start,p_event_kind,v_quantity,round(p_amount/v_quantity,2),p_amount,coalesce(v_occ.description,initcap(replace(v_occ.occurrence_type,'_',' '))),'occurrence:'||v_occ.id::text||':'||p_competence_month::text||':'||p_event_kind);insert into public.employee_occurrence_payroll_links(tenant_id,company_id,occurrence_id,competence_month,payroll_event_id,event_kind,generated_amount,generated_by) values(v_occ.tenant_id,v_occ.company_id,v_occ.id,p_competence_month,v_event_id,p_event_kind,p_amount::numeric(14,2),auth.uid());return v_event_id;end;$$;
create view public.hr_occurrence_payroll_queue with(security_invoker=true) as with expanded as(select o.*,gs::date competence_month,greatest(o.starts_on,gs::date) overlap_start,least(o.ends_on,(gs+interval '1 month - 1 day')::date) overlap_end from public.employee_occurrences o cross join lateral generate_series(date_trunc('month',o.starts_on)::date,date_trunc('month',o.ends_on)::date,interval '1 month') gs where o.status='active' and o.payroll_effect in('absence','dsr')) select e.tenant_id,e.company_id,e.employment_contract_id,e.id occurrence_id,e.occurrence_type,e.payroll_effect event_kind,e.competence_month,e.overlap_start,e.overlap_end,((e.overlap_end-e.overlap_start)+1)::integer days_in_competence,l.payroll_event_id,l.generated_amount,case when l.id is null then 'pending' else 'synced' end payroll_sync_status from expanded e left join public.employee_occurrence_payroll_links l on l.tenant_id=e.tenant_id and l.company_id=e.company_id and l.occurrence_id=e.id and l.competence_month=e.competence_month and l.event_kind=e.payroll_effect;
create view public.hr_employee_status with(security_invoker=true) as select ec.tenant_id,ec.company_id,ec.id employment_contract_id,ec.employee_id,e.full_name,ec.job_title,ec.status contract_status,case when ec.status='terminated' or e.status='inactive' then 'inactive' when exists(select 1 from public.employee_occurrences o where o.tenant_id=ec.tenant_id and o.company_id=ec.company_id and o.employment_contract_id=ec.id and o.status='active' and current_date between o.starts_on and o.ends_on and o.occurrence_type='work_accident') then 'work_accident' when exists(select 1 from public.employee_occurrences o where o.tenant_id=ec.tenant_id and o.company_id=ec.company_id and o.employment_contract_id=ec.id and o.status='active' and current_date between o.starts_on and o.ends_on and o.occurrence_type='leave') then 'leave' when exists(select 1 from public.employee_occurrences o where o.tenant_id=ec.tenant_id and o.company_id=ec.company_id and o.employment_contract_id=ec.id and o.status='active' and current_date between o.starts_on and o.ends_on and o.occurrence_type='vacation') then 'vacation' when exists(select 1 from public.employee_occurrences o where o.tenant_id=ec.tenant_id and o.company_id=ec.company_id and o.employment_contract_id=ec.id and o.status='active' and current_date between o.starts_on and o.ends_on and o.occurrence_type='medical_certificate') then 'medical_certificate' when exists(select 1 from public.employee_occurrences o where o.tenant_id=ec.tenant_id and o.company_id=ec.company_id and o.employment_contract_id=ec.id and o.status='active' and current_date between o.starts_on and o.ends_on and o.occurrence_type='suspension') then 'suspension' when exists(select 1 from public.employee_occurrences o where o.tenant_id=ec.tenant_id and o.company_id=ec.company_id and o.employment_contract_id=ec.id and o.status='active' and current_date between o.starts_on and o.ends_on and o.occurrence_type='absence') then 'absence' else 'active' end operational_status,(select count(*) from public.employee_documents d where d.tenant_id=ec.tenant_id and d.company_id=ec.company_id and d.employment_contract_id=ec.id and d.status='pending') pending_documents,(select count(*) from public.hr_occurrence_payroll_queue q where q.tenant_id=ec.tenant_id and q.company_id=ec.company_id and q.employment_contract_id=ec.id and q.payroll_sync_status='pending') pending_payroll_occurrences from public.employment_contracts ec join public.employees e on e.tenant_id=ec.tenant_id and e.id=ec.employee_id;
commit;
